-- {FINAL} for 11_: fired VERIFIED sessions by bitmask (IDs as in 13_) UNION ALL one totals row over all sessions:
-- 'TOT'|n|clean| then per rule r0..r11 'F,Fh,Fcl,Fv'. Used for Figma 6 Nov (labels all verified).
, y AS (SELECT sid, r0+2*r1+4*r3+8*r4+16*r5+32*r6+64*r7+128*r8+256*r9 mask FROM s4 WHERE ver=1)
SELECT mask::STRING||'|'||COUNT(*)||'|'||LISTAGG(LEFT(RIGHT(sid,10),7)||RIGHT(sid,1), ',') r FROM y WHERE mask>0 GROUP BY mask
UNION ALL SELECT 'TOT|'||COUNT(*)||'|'||SUM(cl)||'|'||SUM(r0)||','||SUM(r0*hi)||','||SUM(r0*cl)||','||SUM(r0*ver)||'|'||SUM(r1)||','||SUM(r1*hi)||','||SUM(r1*cl)||','||SUM(r1*ver)||'|'||SUM(r2)||','||SUM(r2*hi)||','||SUM(r2*cl)||','||SUM(r2*ver)||'|'||SUM(r3)||','||SUM(r3*hi)||','||SUM(r3*cl)||','||SUM(r3*ver)||'|'||SUM(r4)||','||SUM(r4*hi)||','||SUM(r4*cl)||','||SUM(r4*ver)||'|'||SUM(r5)||','||SUM(r5*hi)||','||SUM(r5*cl)||','||SUM(r5*ver)||'|'||SUM(r6)||','||SUM(r6*hi)||','||SUM(r6*cl)||','||SUM(r6*ver)||'|'||SUM(r7)||','||SUM(r7*hi)||','||SUM(r7*cl)||','||SUM(r7*ver)||'|'||SUM(r8)||','||SUM(r8*hi)||','||SUM(r8*cl)||','||SUM(r8*ver)||'|'||SUM(r9)||','||SUM(r9*hi)||','||SUM(r9*cl)||','||SUM(r9*ver)||'|'||SUM(r10)||','||SUM(r10*hi)||','||SUM(r10*cl)||','||SUM(r10*ver)||'|'||SUM(r11)||','||SUM(r11*hi)||','||SUM(r11*cl)||','||SUM(r11*ver) FROM s4
